WITH base AS (SELECT * FROM stores WHERE NOT (city = 'New York' AND (region = 'East' OR region IS NULL))), summary AS (SELECT MONTH(opened_date) AS opened_month, MIN(opened_date) AS first_opened_date, COUNT(DISTINCT sqft) AS unique_regions FROM base GROUP BY MONTH(opened_date)) SELECT opened_month, first_opened_date, unique_regions FROM summary WHERE unique_regions > 5 ORDER BY unique_regions;
